	// 先前保存的结果仍是十件、七件、三件，以及当时两笔承诺的数量与 active
	// 状态，不随仓库变化被改写。
	assertInitialPartSnapshot(t, saved)

	// 仓库记录与数量核算规则一致：取消只释放未用占用，已用实物不补回。
	c5, _ := s.Commitment("c-five")
